//! The Library focus in a window of its own (Window › Library,
//! `library.window`): it opens in an OS window of its own and comes to
//! the front when asked again; it shows the main window's Library, so
//! its selection is the one commands act on and a mark made there is the
//! main window's too; open at the last quit, it opens again at the
//! next start. The snapshot (`tests/snapshots/library-window-*.png`) is
//! regenerated by the box's `gui-snapshots` job with `test=library_window`.

use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

use egui::{ViewportId, vec2};
use egui_kittest::Harness;
use egui_kittest::kittest::Queryable as _;
use egui_pop::api::windows::WindowId;
use helios_gui::library::Entry;
use helios_gui::shell::{LIBRARY_WINDOW, LIBRARY_WINDOW_COMMAND};
use helios_gui::{Shell, headless, helios_panels};
use helios_shell::commands::Origin;
use serde_json::{Value, json};

fn scratch(name: &str) -> PathBuf {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let dir = std::env::temp_dir().join(format!(
        "helios-gui-library-window-{name}-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// Photos a, b and c.
fn entries() -> Vec<Entry> {
    ["a", "b", "c"]
        .iter()
        .map(|id| Entry {
            id: (*id).to_string(),
            name: format!("{id}.jpg"),
            ..Entry::default()
        })
        .collect()
}

fn run(h: &mut Harness<'_, Shell>, command: &str, args: Value) {
    h.state_mut().run(command, args, Origin::User).unwrap();
    h.run_steps(3);
}

/// The windows the main window's last pass declared, as eframe would
/// open them.
fn declared(h: &Harness<'static, Shell>) -> Vec<ViewportId> {
    h.output()
        .viewport_output
        .iter()
        .filter(|(v, o)| **v != ViewportId::ROOT && o.viewport_ui_cb.is_some())
        .map(|(v, _)| *v)
        .collect()
}

#[test]
fn window_library_opens_the_focus_in_its_own_window_and_again_brings_it_forward() {
    let mut h = headless::harness(Shell::new(helios_panels(), None), vec2(1280.0, 800.0));
    h.ctx.set_embed_viewports(false);
    h.state_mut().draw_frame(true);
    h.run();
    assert!(declared(&h).is_empty(), "no window but the main one");
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    let windows = declared(&h);
    assert_eq!(windows.len(), 1, "the focus's own window: {windows:?}");
    let app = h.state().app().handle().clone();
    assert_eq!(
        app.window_viewport(&WindowId::new(LIBRARY_WINDOW)),
        Some(windows[0])
    );
    // Asked again: the same window, not a second one.
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    assert_eq!(declared(&h), windows);
    // Closed: the focus closes, the main window stays.
    app.close_window(&WindowId::new(LIBRARY_WINDOW));
    h.run_steps(3);
    assert!(declared(&h).is_empty());
    assert_eq!(h.state().library_window_state()["open"], false);
}

/// The cell labelled `name` in the Library window: the main window's
/// filmstrip draws one too, under the window and partly within its
/// area, so the cell is looked for among the window's own nodes.
fn in_window<'a>(h: &'a Harness<'_, Shell>, name: &'a str) -> egui_kittest::Node<'a> {
    h.get_by_role_and_label(egui::accesskit::Role::Window, "Library")
        .get_by_label(name)
}

/// A pointer press and release on `at`, each on frames of its own, as a
/// hand clicks: the grid's cells also sense drags.
fn click_at(h: &mut Harness<'_, Shell>, at: egui::Pos2) {
    h.event(egui::Event::PointerMoved(at));
    h.run_steps(1);
    for pressed in [true, false] {
        h.event(egui::Event::PointerButton {
            pos: at,
            button: egui::PointerButton::Primary,
            pressed,
            modifiers: egui::Modifiers::NONE,
        });
        h.run_steps(2);
    }
}

#[test]
fn the_library_window_s_selection_is_the_one_commands_act_on() {
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    assert_eq!(h.state().library_window_state()["open"], true);
    // A click on b in the window's grid: one selection for both windows.
    let at = in_window(&h, "b.jpg").rect().center();
    click_at(&mut h, at);
    assert_eq!(h.state().library().selected, Some(1));
    // A command, from wherever it comes, acts on that selection.
    run(&mut h, "vault.rate", json!({ "stars": 4 }));
    let library = h.state().library();
    assert_eq!(library.entries[1].rating, 4);
    assert_eq!(library.entries[0].rating, 0, "only the selection");
}

#[test]
fn a_click_on_a_cell_of_the_library_window_selects_it() {
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    // Through accesskit, as agents and screen readers click.
    in_window(&h, "a.jpg").click_accesskit();
    h.run_steps(2);
    assert_eq!(h.state().library().selected, Some(0), "a, clicked");
    // With the pointer, the cell under it; the main window's filmstrip,
    // drawn under the window, does not take the click.
    let at = in_window(&h, "c.jpg").rect().center();
    click_at(&mut h, at);
    assert_eq!(h.state().library().selected, Some(2), "c, clicked");
}

#[test]
fn the_library_window_open_at_the_last_quit_opens_again_at_the_start() {
    let dir = scratch("restore");
    {
        let shell = Shell::build(helios_panels(), None, Some(dir.clone()));
        let mut h = headless::harness(shell, vec2(1280.0, 800.0));
        h.run();
        run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
        h.state().app().handle().flush_documents();
    }
    let shell = Shell::build(helios_panels(), None, Some(dir.clone()));
    assert_eq!(shell.library_window_state()["open"], true, "opened again");
    let mut h = headless::harness(shell, vec2(1280.0, 800.0));
    h.run();
    // Closed, it stays closed at the next start.
    h.state_mut().close_library_window();
    h.run_steps(3);
    h.state().app().handle().flush_documents();
    drop(h);
    let shell = Shell::build(helios_panels(), None, Some(dir.clone()));
    assert_eq!(shell.library_window_state()["open"], false);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn library_window_snapshots() {
    let mut results = egui_kittest::SnapshotResults::new();
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    shell.library_mut().select(1);
    let mut h = headless::harness(shell, vec2(1280.0, 800.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    h.run_steps(4);
    results.add(h.try_snapshot("library-window-pop-dark-1x"));
}
